head.script:
// 원본 : /lstproc/ULDSTF05621.gfm (분배기준일변경관리 팝업)
/*
 * 화면 동작
 *  - 부모(ULDSTF05620)가 넘긴 업무처리번호가 없으면 신규, 있으면 수정이다.
 *  - 신규: 회사의 현재 수입분배기준일을 "변경전"에 채우고, "변경후"에는 입력할 빈 행 13개를 깐다.
 *  - 저장: 검증 → 확인 → 예약 건 확인 → 채번 → 등록. 수정·삭제는 업무처리번호 기준.
 *  - 공시안내문작성(ULDSTF92024)·기안(ULDSTF92004)은 openPopup 의 data 로 넘기고 await 한다.
 *    92024 전환본이 아직 부모 getPar 를 부르므로 호환용 scwin.getPar 만 임시로 둔다(§10 #7).
 * 업무 분석 : conversion/gfm-front/ui/ULDSTF05621/ULDSTF05621.md (§번호는 이 문서의 절)
 */

///////// 1. 변수 및 선언 영역 /////////

scwin.screenId = "ULDSTF05621";
scwin.API = "/api/listing/lstproc/fund/dist-pay-basdd-change/";

// 부모 화면에서 넘겨받는 값 (§1.2)
scwin.isurCd = "";          // 발행기관코드
scwin.isurNm = "";          // 발행기관명
scwin.bzProcsNo = "";       // 업무처리번호 — 비어 있으면 신규, 있으면 수정

// 화면 상태값
scwin.trJob = "";           // 처리구분 I: 저장, U: 수정, D: 삭제
scwin.curDate = "";         // 서버 현재일 (yyyyMMdd)
scwin.savedState = "";      // 조회 직후 마스터·변경후 목록 — 수정할 내용이 있는지 판정용 (원본 IsUpdated)

// 고정값
scwin.AF_ROW_COUNT = 13;            // 변경후 그리드 행 수 — 원본 OnLoadCompleted 의 결과(주석은 12, §8 #1)
scwin.DSCL_FORM_CD = "68212C";      // 공시안내문 서식코드 — 분배기준일변경 안내공시
scwin.DSCL_MKT_ID = "1";            // 공시안내문 시장구분 — 원본도 유가 고정 (§8 #11)

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
scwin.BTN_MAP = {
    save : "btn_Save",          // [저장]
    modify : "btn_Update",      // [수정]
    "delete" : "btn_Delete",    // [삭제]
    draft : "btn_Drft",         // [기안]
    guide : "btn_Dscl"          // [안내문작성]
};


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 26
 * @description 페이지로드. 파라미터를 받고 업무처리번호 유무로 신규 준비 또는 수정 조회를 한다. (§3)
 * @param
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        // 로딩이 끝나거나 조회가 예외로 끝나도 버튼이 XML 기본값(전부 활성)으로 남지 않게 먼저 잠근다.
        $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);

        scwin.init_recvParam();

        if ($c.util.isEmpty(scwin.bzProcsNo)) {
            await scwin.init_newForm();
        } else {
            await scwin.selectOne();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05621.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 10. 26
 * @description 부모가 openPopup 의 data 로 넘긴 값을 받는다. (원본 frame.Provider("../").fn_GetPar(arrPar) — §1.2)
 * 날짜 입력 형식과 서버 현재일도 여기서 정한다.
 * @param
 * @returns
 * @hidden N
 */
scwin.init_recvParam = function () {
    const param = $c.data.getParameter() ?? {};

    scwin.isurCd = param.isurCd ?? "";          // AS-IS arr[0]
    scwin.isurNm = param.isurNm ?? "";          // AS-IS arr[1]
    scwin.bzProcsNo = param.bzProcsNo ?? "";    // AS-IS arr[4]

    $c.date.checkCalendarFormat(edt_CHG_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_MKTACT_ENFORCE_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_ChgStatDd, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_ChgEndDd, "yyyyMMdd");

    scwin.curDate = $c.date.getServerDateTime("yyyyMMdd");
};

/**
 * @method
 * @name scwin.init_newForm
 * @author Inswave
 * @date 2026. 10. 26
 * @description 신규 준비. 마스터를 비우고, 현재 수입분배기준일을 "변경전"에 채운 뒤 "변경후" 빈 행을 깔고 [저장]만 켠다.
 * (원본 fn_new_onload + dts_Mst/dts_DtlAf OnLoadCompleted — §3, §1.4 업무 1)
 * @param
 * @returns
 * @hidden N
 */
scwin.init_newForm = async function () {
    dma_resultDetail.setEmptyValue();
    dlt_resultDetail_dtlBfList.removeAll();
    dlt_resultDetail_dtlAfList.removeAll();

    // 신규는 부모 값으로 회사를 표시한다 (수정은 조회 응답 값 — §8 #8).
    dma_resultDetail.set("isurCd", scwin.isurCd);
    dma_resultDetail.set("isurNm", scwin.isurNm);

    await scwin.selectCurrentBasdd();
    scwin.fillAfRows();

    $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_Save_onclick
 * @author Inswave
 * @date 2026. 10. 26
 * @description 저장 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Save_onclick = async function (e) {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05621.btn_Save_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_Update_onclick
 * @author Inswave
 * @date 2026. 10. 26
 * @description 수정 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Update_onclick = async function (e) {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05621.btn_Update_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_Delete_onclick
 * @author Inswave
 * @date 2026. 10. 26
 * @description 삭제 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Delete_onclick = async function (e) {
    try {
        await scwin.remove();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05621.btn_Delete_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_Dscl_onclick
 * @author Inswave
 * @date 2026. 10. 26
 * @description 안내문작성 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Dscl_onclick = async function (e) {
    try {
        await scwin.writeDscl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05621.btn_Dscl_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_Drft_onclick
 * @author Inswave
 * @date 2026. 10. 26
 * @description 기안 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Drft_onclick = async function (e) {
    try {
        await scwin.writeDraft();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05621.btn_Drft_onclick" });
    }
};

/**
 * @event
 * @name scwin.grd_DIST_PAY_AF_onafteredit
 * @author Inswave
 * @date 2026. 10. 26
 * @description 변경후 월·일 편집 직후 범위 확인. 월 > 12, 일 > 31 이면 안내하고 그 칸을 비운다. (원본 OnExit — §6.3)
 * 월별 말일(0231 등)은 원본도 보지 않는다(§8 #4).
 * @param {Number} row 행 index
 * @param {Number} col 컬럼 index
 * @param {String} value 입력값
 * @returns
 * @hidden N
 */
scwin.grd_DIST_PAY_AF_onafteredit = async function (row, col, value) {
    try {
        const colId = grd_DIST_PAY_AF.getColumnID(col);
        const val = Number(dlt_resultDetail_dtlAfList.getCellData(row, colId));

        if (colId === "basMm" && val > 12) {
            await $c.win.alert("입력월을 확인하세요.");
            dlt_resultDetail_dtlAfList.setCellData(row, "basMm", "");
        } else if (colId === "basDd" && val > 31) {
            await $c.win.alert("입력일을 확인하세요.");
            dlt_resultDetail_dtlAfList.setCellData(row, "basDd", "");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05621.grd_DIST_PAY_AF_onafteredit" });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.selectCurrentBasdd
 * @author Inswave
 * @date 2026. 10. 26
 * @description 신규: 회사의 현재 수입분배기준일 목록을 "변경전"에 채운다. (원본 DIV_IDX_DTL_DIST_BF + TRS_IDX_NEWSEL2 — §5.1)
 * @param
 * @returns
 * @hidden N
 */
scwin.selectCurrentBasdd = async function () {
    const sbmOptions = {
        id : "sbm_selectCurrentBasdd",
        method : "get",
        action : scwin.API + "select-current-dist-pay-basdd",
        // TODO: 명세 응답이 dataMap(dma_std)으로 적혀 있으나 그리드는 여러 행 — 목록인지 확인 (§10 #1)
        target : "dlt_resultDetail_dtlBfList=body",
        gridview : "grd_DIST_PAY_BF",
        isProcessMsg : false
    };

    // 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다.
    await $c.sbm.executeDynamic(sbmOptions, { isurCd : scwin.isurCd });
};

/**
 * @method
 * @name scwin.selectOne
 * @author Inswave
 * @date 2026. 10. 26
 * @description 수정: 업무처리번호로 마스터와 변경전·변경후 목록을 조회하고, 시장조치시행일로 버튼 상태를 정한다.
 * (원본 fn_search 동기 3회 → 1회, dts_Mst OnLoadCompleted — §5.2)
 * @param
 * @returns
 * @hidden N
 */
scwin.selectOne = async function () {
    const sbmOptions = {
        id : "sbm_selectOne",
        method : "get",
        action : scwin.API + "select-one",
        // TODO: 목록 키(dtlBfList/dtlAfList)는 명세 이름에서 추정한 가정 (§10 #1)
        target : "dma_resultDetail=body,dlt_resultDetail_dtlBfList=body.dtlBfList,dlt_resultDetail_dtlAfList=body.dtlAfList",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { bzProcsNo : scwin.bzProcsNo });
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    // 실패하면 onpageload 가 걸어 둔 잠금(disabled) 그대로 둔다.
    if (!result.responseJSON?.success) return;

    scwin.fillAfRows();
    scwin.savedState = scwin.getEditState();

    // 시장조치시행일이 오늘 이후면 update, 지났으면 error(기안만)
    $c.stf.setButtonSetWithDate(edt_MKTACT_ENFORCE_DD, false, "grpBtnBox", scwin.BTN_MAP);
};

/**
 * @method
 * @name scwin.checkMst
 * @author Inswave
 * @date 2026. 10. 26
 * @description 현재일 이후로 예약된 분배기준일변경 건이 있는지 확인한다. 있으면 MSG-0011 을 안내하고 false. (원본 fn_mst_check(dts_Mst_Check, "2") — §5.3)
 * pcc $c.lc.mstCheck 는 AS-IS URL·미선언 전역을 써서 쓰지 않는다(§8 #13).
 * @param
 * @returns {Promise<Boolean>} 진행해도 되면 true
 * @hidden N
 */
scwin.checkMst = async function () {
    const sbmOptions = {
        id : "sbm_checkMst",
        method : "get",
        action : scwin.API + "select-mst-check",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { isurCd : scwin.isurCd });
    if (result?.skipped) return false;
    if (!result.responseJSON?.success) return false;

    // TODO: boolean 의 뜻(true = 예약 건 있음)은 가정 — 명세 확인 필요 (§10 #4)
    if (result.responseJSON.body === true) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0011", ""));
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.saveTrs
 * @author Inswave
 * @date 2026. 10. 26
 * @description 신규 저장(I)·수정(U). 마스터와 변경전·변경후 목록을 한 전문으로 보내고, 성공하면 다시 조회한다.
 * (원본 fn_save_trs + trs OnSuccess/OnFail — §5.5, §5.6)
 * 목록은 복사본으로 만들어 그리드 dataList 는 건드리지 않는다(§8 #5).
 * @param {String} trJob 처리구분 I: 저장, U: 수정
 * @param {String} bzProcsNo 업무처리번호 (신규는 채번한 값)
 * @returns
 * @hidden N
 */
scwin.saveTrs = async function (trJob, bzProcsNo) {
    const jobNm = (trJob === "I") ? "저장" : "수정";

    const sbmOptions = {
        id : "sbm_saveTrs",
        method : "post",
        action : scwin.API + ((trJob === "I") ? "insert" : "update"),
        mediatype : "application/json",
        isProcessMsg : false
    };

    // 요청 전문은 명세 정의(insert: dma_reqSave·dlt_reqSave_*, update: dma_reqUpdate·dlt_reqUpdate_*)에 담아 보낸다.
    // setJSON 은 정의된 키만 남기므로 명세에 없는 값은 보내지 않는다.
    // TODO: 원본은 FISCYY_DISTR_BASDD_TP_CD="2"·LIST_BZ_TP_CD 232 를 보냈으나 신규 명세에 없음 — 서버 처리 여부 확인 (§10 #3)
    // TODO: 신규 명세는 bzProcsNo 를 "수정 시에만 전달" — 채번 주체 확인 (§10 #2)
    const isInsert = (trJob === "I");
    const reqMst = isInsert ? dma_reqSave : dma_reqUpdate;
    const reqBf = isInsert ? dlt_reqSave_dtlBfList : dlt_reqUpdate_dtlBfList;
    const reqAf = isInsert ? dlt_reqSave_dtlAfList : dlt_reqUpdate_dtlAfList;

    reqMst.setEmptyValue();
    reqMst.setJSON({
        bzProcsNo : bzProcsNo,
        isurCd : scwin.getIsurCd(),
        chgDd : dma_resultDetail.get("chgDd"),
        mktactEnforceDd : dma_resultDetail.get("mktactEnforceDd"),
        fiscyyChgRsnCd : dma_resultDetail.get("fiscyyChgRsnCd"),
        remk : dma_resultDetail.get("remk"),
        fiscyyChgStrtDd : dma_resultDetail.get("fiscyyChgStrtDd"),
        fiscyyChgEndDd : dma_resultDetail.get("fiscyyChgEndDd")
    });
    reqBf.setJSON(scwin.buildDtlList(dlt_resultDetail_dtlBfList, "1", bzProcsNo));
    reqAf.setJSON(scwin.buildDtlList(dlt_resultDetail_dtlAfList, "2", bzProcsNo));

    // TODO: 목록 키(dtlBfList/dtlAfList)는 명세 정의 이름(dlt_req*_dtlBfList)에서 추정한 가정 (§10 #1)
    const requestData = {
        ...reqMst.getJSON(),
        dtlBfList : reqBf.getAllJSON(),
        dtlAfList : reqAf.getAllJSON()
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!result.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", jobNm));
        return;
    }

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", jobNm));

    // 성공한 뒤에만 업무처리번호를 확정한다 — 실패한 신규 번호가 남지 않게(§8 #7).
    scwin.bzProcsNo = bzProcsNo;
    await scwin.selectOne();
};

/**
 * @method
 * @name scwin.deleteTrs
 * @author Inswave
 * @date 2026. 10. 26
 * @description 삭제. 성공하면 팝업을 닫는다 — 부모는 await 가 끝나면 목록을 다시 조회한다. (원본 TRS_IDX_DELETE + buttonSet.status "D" — §5.7)
 * @param
 * @returns
 * @hidden N
 */
scwin.deleteTrs = async function () {
    const sbmOptions = {
        id : "sbm_deleteTrs",
        method : "post",
        action : scwin.API + "delete",
        mediatype : "application/json",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { bzProcsNo : scwin.bzProcsNo });
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!result.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
        return;
    }

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    $c.win.closePopup();
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 26
 * @description 저장·수정 전 입력 검증. 원본 fn_CheckForm 순서를 따른다. (§6.1)
 *  1) 변경후 월·일은 두 자리씩 4자리  2) 변경일·시장조치시행일·변경사유 필수, 기타 2000 byte (공통 검증)
 *  3) 시장조치시행일은 익일 이후 (원본 checkDdTm — pcc 함수는 Gauce 속성 .text 를 읽어 쓰지 않는다)
 * @param
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
 */
scwin.validate = async function () {
    const rowCount = dlt_resultDetail_dtlAfList.getRowCount();
    let badRow = -1;

    dlt_resultDetail_dtlAfList.setBroadcast(false);
    for (let i = 0; i < rowCount; i++) {
        const mmdd = String(dlt_resultDetail_dtlAfList.getCellData(i, "basMm") ?? "") + String(dlt_resultDetail_dtlAfList.getCellData(i, "basDd") ?? "");
        dlt_resultDetail_dtlAfList.setCellData(i, "basMmdd", mmdd);
        if (badRow < 0 && mmdd !== "" && mmdd.length !== 4) badRow = i;
    }
    dlt_resultDetail_dtlAfList.setBroadcast(true, true);

    if (badRow >= 0) {
        await $c.win.alert("입력한 항목중 [변경후(월,일)]을 정확히 입력해주세요. \n\n예 : 5월1일 -> 0501 ");
        grd_DIST_PAY_AF.setFocusedCell(badRow, "basMm");
        return false;
    }

    const dateOptions = {
        validateType : "alert",     // alert|mark|all
        checkType : "single",       // single|multi
        fields : {
            edt_CHG_DD : { required : true, format : "date", name : "변경일" },
            edt_MKTACT_ENFORCE_DD : { required : true, format : "date", name : "시장조치시행일" }
        }
    };
    if (!await $c.validate.validateDataCollect(panel_3, dateOptions)) return false;

    // 시장조치시행일은 익일 이후 (원본 checkDdTm("DD", …, false)) — 원본 순서대로 변경사유보다 먼저 본다.
    if (dma_resultDetail.get("mktactEnforceDd") <= scwin.curDate) {
        await $c.win.alert("[시장조치시행일]을 익일 이후로 입력하세요.");
        edt_MKTACT_ENFORCE_DD.focus();
        return false;
    }

    const etcOptions = {
        validateType : "alert",
        checkType : "single",
        fields : {
            cmb_FISCYY_CHG_RSN_CD : { required : true, name : "변경사유" },
            txa_REMK : { maxLengthB : 2000, name : "기타" }
        }
    };
    if (!await $c.validate.validateDataCollect(panel_3, etcOptions)) return false;

    // TODO: 변경 후 최초 사업연도 시작·종료일, 변경후 0건은 필수 표시가 있으나 원본도 검증하지 않음 (§8 #9, §10 #9)
    return true;
};

/**
 * @method
 * @name scwin.fillAfRows
 * @author Inswave
 * @date 2026. 10. 26
 * @description 변경후 그리드에 입력할 빈 행을 채워 AF_ROW_COUNT 행으로 맞춘다. (원본 dts_DtlAf OnLoadCompleted — §6.2)
 * @param
 * @returns
 * @hidden N
 */
scwin.fillAfRows = function () {
    dlt_resultDetail_dtlAfList.setBroadcast(false);
    while (dlt_resultDetail_dtlAfList.getRowCount() < scwin.AF_ROW_COUNT) {
        dlt_resultDetail_dtlAfList.insertRow();
    }
    dlt_resultDetail_dtlAfList.setBroadcast(true, true);
};

/**
 * @method
 * @name scwin.buildDtlList
 * @author Inswave
 * @date 2026. 10. 26
 * @description 저장 전문의 변경전(1)·변경후(2) 목록을 만든다. 변경후는 월·일이 빈 행을 빼고 일련번호를 13부터 매긴다.
 * (원본 fn_save_trs 의 두 루프 — BYBZPROCS_SEQ 변경전 i, 변경후 i + 12)
 * @param {Object} dataList 대상 dataList (dlt_resultDetail_dtlBfList / dlt_resultDetail_dtlAfList)
 * @param {String} chgBfafTpCd 변경전후구분코드 1: 변경전, 2: 변경후
 * @param {String} bzProcsNo 업무처리번호
 * @returns {Array} 전송할 행 목록
 * @hidden N
 */
scwin.buildDtlList = function (dataList, chgBfafTpCd, bzProcsNo) {
    const isAfter = (chgBfafTpCd === "2");
    const seqBase = isAfter ? 12 : 0;

    return dataList.getAllJSON()
        .filter(row => !isAfter || !$c.util.isEmpty(row.basMmdd))
        .map((row, i) => ({
            ...row,
            bzProcsNo : bzProcsNo,
            bybzprocsSeq : seqBase + i + 1,
            isurCd : scwin.getIsurCd(),
            chgBfafTpCd : chgBfafTpCd
        }));
};

/**
 * @method
 * @name scwin.getEditState
 * @author Inswave
 * @date 2026. 10. 26
 * @description 수정 여부 판정용으로 마스터와 변경후 목록을 문자열로 묶는다. (원본 dts_Mst.IsUpdated || dts_DtlAf.IsUpdated)
 * 변경후 그리드는 빈 행을 채워 넣어 행 상태(C)로는 판정할 수 없어 값을 비교한다.
 * @param
 * @returns {String} 현재 상태 문자열
 * @hidden N
 */
scwin.getEditState = function () {
    const af = dlt_resultDetail_dtlAfList.getAllJSON().map(row => [row.basMm ?? "", row.basDd ?? ""]);
    return JSON.stringify([dma_resultDetail.getJSON(), af]);
};

/**
 * @method
 * @name scwin.getNewBzProcsNo
 * @author Inswave
 * @date 2026. 10. 26
 * @description 업무처리번호를 새로 받는다. $c.stf.getNewBzProcNo 는 응답 봉투를 그대로 돌려줄 수 있어 body 를 꺼내 문자열로 만든다. (§5.4)
 * @param
 * @returns {Promise<String>} 업무처리번호 (실패면 빈 문자열)
 * @hidden N
 */
scwin.getNewBzProcsNo = async function () {
    const res = await $c.stf.getNewBzProcNo();
    const value = (res !== null && typeof res === "object") ? res.body : res;
    return String(value ?? "");
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 26
 * @description 신규 저장. 검증 → 확인 → 예약 건 확인 → 채번 → 등록 순서 (원본 fn_save — §6.6, §1.4 업무 2)
 * 채번이 확인보다 뒤라서 취소한 건에는 번호가 소비되지 않는다.
 * @param
 * @returns
 * @hidden N
 */
scwin.save = async function () {
    scwin.trJob = "I";

    if (!await scwin.validate()) return;

    // "[저장] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    if (!await scwin.checkMst()) return;

    const bzProcsNo = await scwin.getNewBzProcsNo();
    if (bzProcsNo.length !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }

    await scwin.saveTrs(scwin.trJob, bzProcsNo);
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 26
 * @description 수정. 검증 → 바뀐 내용 확인 → 확인 → 수정 순서 (원본 fn_update — §6.7, §1.4 업무 3)
 * @param
 * @returns
 * @hidden N
 */
scwin.update = async function () {
    scwin.trJob = "U";

    if (!await scwin.validate()) return;

    if (scwin.getEditState() === scwin.savedState) {
        // TODO: 원본 공통 fn_alertNoUpdate 문구 확인 (§10 #12)
        await $c.win.alert("변경된 내용이 없습니다.");
        return;
    }

    // "[수정] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.saveTrs(scwin.trJob, scwin.bzProcsNo);
};

/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 10. 26
 * @description 삭제. 확인을 받은 뒤 삭제한다. 입력 검증은 하지 않는다. (원본 fn_delete — §6.8, §1.4 업무 4)
 * @param
 * @returns
 * @hidden N
 */
scwin.remove = async function () {
    scwin.trJob = "D";

    // "[삭제] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.deleteTrs();
};

/**
 * @method
 * @name scwin.getDsclData
 * @author Inswave
 * @date 2026. 10. 26
 * @description 공시안내문작성(ULDSTF92024)에 넘길 값. 원본 fn_dscl 이 fn_GetPar 로 채우던 arr[0..3] 과 데이터셋 3개다. (§6.4)
 * @param
 * @returns {Object} 넘길 data
 * @hidden N
 */
scwin.getDsclData = function () {
    return {
        formCd : scwin.DSCL_FORM_CD,            // AS-IS arr[0]
        bzProcsNo : scwin.bzProcsNo,            // AS-IS arr[1]
        isurCd : scwin.getIsurCd(),             // AS-IS arr[2]
        mktId : scwin.DSCL_MKT_ID,              // AS-IS arr[3]
        mst : [dma_resultDetail.getJSON()],              // AS-IS CopyDataSet(dts_Mst, param_dts_mst)
        dtl2 : dlt_resultDetail_dtlBfList.getAllJSON(),          // AS-IS CopyDataSet(dts_DtlBf, param_dts2)
        dtl3 : dlt_resultDetail_dtlAfList.getAllJSON()           // AS-IS CopyDataSet(dts_DtlAf, param_dts3) + 월·일 빈 행 삭제
            .filter(row => !($c.util.isEmpty(row.basMm) && $c.util.isEmpty(row.basDd)))
    };
};

/**
 * @method
 * @name scwin.writeDscl
 * @author Inswave
 * @date 2026. 10. 26
 * @description 공시안내문작성 팝업을 data 로 넘겨 열고 닫힐 때까지 기다린다. 돌려받는 값은 없다. (원본 fn_dscl — §6.4, 가이드 §6.5)
 * @param
 * @returns
 * @hidden N
 */
scwin.writeDscl = async function () {
    const options = {
        id : "ULDSTF92024",
        popupName : "공시안내문작성",
        width : 735,
        height : 815,
        type : "pageFramePopup"
    };

    // TODO: 경로는 가정, 92024 는 아직 getPar 계약이라 수신부 변경 필요 (§10 #7)
    await $c.win.openPopup("/ui/listingcommon/ULDSTF92024.xml", options, scwin.getDsclData());
};

/**
 * @method
 * @name scwin.getPar
 * @author Inswave
 * @date 2026. 10. 26
 * @description [호환용 · 임시] 공시안내문작성(ULDSTF92024) 전환본은 아직 부모의 scwin.getPar 를 이름으로 불러 값을 받는다.
 * 92024 가 $c.data.getParameter() 수신으로 바뀌면 이 함수를 지운다. (§6.4, §10 #7, 가이드 §6.5 예외)
 * @param {Array} arr 92024 가 넘기는 빈 배열 — [0] 서식코드 [1] 업무처리번호 [2] 발행기관코드 [3] 시장구분 을 채운다
 * @param {Object} dltIsu 92024 의 종목 dataList (원본도 넘기지 않음)
 * @param {Object} dltMst 92024 의 마스터 dataList
 * @param {Object} dlt2 92024 의 원천 자료 2 (변경전)
 * @param {Object} dlt3 92024 의 원천 자료 3 (변경후)
 * @returns {Number} arr 길이
 * @hidden N
 */
scwin.getPar = function (arr, dltIsu, dltMst, dlt2, dlt3) {
    const data = scwin.getDsclData();

    arr[0] = data.formCd;
    arr[1] = data.bzProcsNo;
    arr[2] = data.isurCd;
    arr[3] = data.mktId;

    scwin.fillDataList(dltMst, data.mst);
    scwin.fillDataList(dlt2, data.dtl2);
    scwin.fillDataList(dlt3, data.dtl3);

    return arr.length;
};

/**
 * @method
 * @name scwin.getIsurCd
 * @author Inswave
 * @date 2026. 10. 26
 * @description 전문에 넣을 회사코드. 수정은 조회 응답 값, 신규는 부모가 넘긴 값이다. (§8 #8)
 * @param
 * @returns {String} 회사코드
 * @hidden N
 */
scwin.getIsurCd = function () {
    return dma_resultDetail.get("isurCd") || scwin.isurCd;
};

/**
 * @method
 * @name scwin.fillDataList
 * @author Inswave
 * @date 2026. 10. 26
 * @description 컬럼 정의가 비어 있는 다른 화면의 dataList 에 행을 채운다. setJSON 은 선언된 컬럼만 옮기므로 첫 행의 키로 컬럼을 먼저 만든다.
 * (92024 의 원천 자료 dataList 는 서식마다 컬럼이 달라 부모가 컬럼째 넘긴다 — 원본 CopyDataSet)
 * @param {Object} dataList 채울 dataList (없으면 무시)
 * @param {Array} rows 넣을 행 목록
 * @returns
 * @hidden N
 */
scwin.fillDataList = function (dataList, rows) {
    if (!dataList) return;

    Object.keys(rows[0] ?? {}).forEach(key => {
        if (dataList.getColumnIndex(key) < 0) dataList.insertColumn(key);
    });
    dataList.setJSON(rows);
};

/**
 * @method
 * @name scwin.writeDraft
 * @author Inswave
 * @date 2026. 10. 26
 * @description 기안문작성 팝업을 업무처리번호와 함께 열고 닫힐 때까지 기다린다. (원본 fn_drft — §6.5)
 * pcc $c.lc.popFindDraft 는 값을 넘기지 않는 콜백형이라 쓰지 않는다.
 * @param
 * @returns
 * @hidden N
 */
scwin.writeDraft = async function () {
    const options = {
        id : "ULDSTF92004",
        popupName : "기안문작성",
        width : 888,
        height : 730,
        type : "pageFramePopup"
    };

    // TODO: 기안 팝업 전환본이 없어 경로·수신 키(bzProcsNo)는 가정 (§10 #8)
    await $c.win.openPopup("/ui/listingcommon/ULDSTF92004.xml", options, { bzProcsNo : scwin.bzProcsNo });
};
